-- Each statement returns a count of violations. Zero means success.
-- Administrative closure is independently acknowledged. Missing bags never get physical receipts.
SELECT COUNT(*) FROM sorting_db.sorting_manifest m LEFT JOIN sorting_db.sorting_manifest_close c ON c.manifest_no=m.manifest_no WHERE m.manifest_status IN ('CLOSING','CLOSED') AND c.manifest_no IS NULL;
SELECT COUNT(*) FROM sorting_db.sorting_manifest m WHERE m.manifest_status='CLOSED' AND (SELECT COUNT(*) FROM sorting_db.sorting_close_outbox o WHERE o.manifest_no=m.manifest_no AND o.status='SENT')<>2;
SELECT COUNT(*) FROM sorting_db.sorting_manifest_package p JOIN sorting_db.sorting_bag_receipt r ON r.manifest_no=p.manifest_no AND r.bag_no=p.package_no WHERE p.item_status='MISSING';
SELECT COUNT(*) FROM transport_db.transport_manifest_assignment a LEFT JOIN transport_db.transport_manifest_close_inbox c ON c.assignment_no=a.assignment_no WHERE a.status='SETTLED' AND c.assignment_no IS NULL;
SELECT COUNT(*) FROM sorting_db.sorting_bag_position p WHERE p.container_status='MISSING' AND NOT EXISTS (SELECT 1 FROM sorting_db.sorting_bag_handoff h WHERE h.bag_no=p.bag_no AND h.manifest_no=p.outgoing_manifest_no AND h.status='MISSING');
SELECT COUNT(*) FROM transport_db.transport_manifest_current c JOIN transport_db.transport_manifest_assignment a ON a.assignment_no=c.assignment_no WHERE c.manifest_no<>a.manifest_no OR a.status IN ('RELEASED','RECEIVED','SETTLED');
SELECT COUNT(*) FROM transport_db.transport_bag_current c JOIN transport_db.transport_manifest_assignment a ON a.assignment_no=c.assignment_no LEFT JOIN transport_db.transport_receipt_inbox r ON r.assignment_no=c.assignment_no AND r.bag_no=c.bag_no WHERE a.status IN ('RELEASED','RECEIVED','SETTLED') OR r.event_no IS NOT NULL;
SELECT COUNT(*) FROM transport_db.transport_manifest_assignment a LEFT JOIN transport_db.transport_manifest_current c ON c.assignment_no=a.assignment_no WHERE a.status NOT IN ('RELEASED','RECEIVED','SETTLED') AND c.assignment_no IS NULL;
SELECT COUNT(*) FROM transport_db.transport_assignment_bag b JOIN transport_db.transport_manifest_assignment a ON a.assignment_no=b.assignment_no LEFT JOIN transport_db.transport_bag_current c ON c.assignment_no=b.assignment_no AND c.bag_no=b.bag_no LEFT JOIN transport_db.transport_receipt_inbox r ON r.assignment_no=b.assignment_no AND r.bag_no=b.bag_no WHERE a.status NOT IN ('RELEASED','RECEIVED','SETTLED') AND c.bag_no IS NULL AND r.event_no IS NULL;
SELECT COUNT(*) FROM transport_db.transport_assignment_bag b JOIN transport_db.transport_manifest_assignment a ON a.assignment_no=b.assignment_no LEFT JOIN transport_db.transport_receipt_inbox r ON r.assignment_no=b.assignment_no AND r.bag_no=b.bag_no WHERE a.status='RECEIVED' AND (r.event_no IS NULL OR a.received_at IS NULL);
SELECT COUNT(*) FROM transport_db.transport_manifest_assignment a JOIN transport_db.transport_task t ON t.id=a.task_id WHERE t.status='COMPLETED' AND a.status NOT IN ('RECEIVED','SETTLED');
SELECT COUNT(*) FROM sorting_db.sorting_bag_position p JOIN sorting_db.sorting_bag_receipt r ON r.event_no=p.last_event_no WHERE p.bag_no<>r.bag_no OR p.facility_code<>r.destination_org_code OR p.last_manifest_no<>r.manifest_no;
SELECT COUNT(*) FROM sorting_db.sorting_bag_receipt r LEFT JOIN sorting_db.sorting_receipt_outbox t ON t.event_no=r.event_no AND t.destination='TRANSPORT' LEFT JOIN sorting_db.sorting_receipt_outbox d ON d.event_no=r.event_no AND d.destination='DISPATCH' WHERE t.event_no IS NULL OR d.event_no IS NULL;
SELECT COUNT(*) FROM sorting_db.sorting_receipt_outbox o WHERE o.status NOT IN ('PENDING','SENDING','RETRY','SENT','CONFLICT') OR o.attempt_count<0 OR (o.status='SENT' AND (o.receipt_json IS NULL OR o.confirmed_at IS NULL));
SELECT COUNT(*) FROM transport_db.transport_assignment_outbox o WHERE o.status NOT IN ('PENDING','SENDING','RETRY','SENT','CONFLICT') OR o.attempt_count<0 OR (o.status='SENT' AND o.receipt_json IS NULL);
SELECT COUNT(*) FROM transport_db.transport_manifest_assignment a JOIN transport_db.transport_task t ON t.id=a.task_id WHERE (t.status='CANCELLED' AND a.status<>'RELEASED') OR (a.status='RELEASED' AND a.released_at IS NULL);
SELECT COUNT(*) FROM dispatch_db.dispatch_manifest_assignment a JOIN dispatch_db.dispatch_batch d ON d.manifest_no=a.manifest_no JOIN dispatch_db.dispatch_batch_bag bb ON bb.batch_no=d.batch_no JOIN dispatch_db.dispatch_bag b ON b.bag_no=bb.bag_no WHERE NOT (b.transport_task_code <=> a.task_code) OR d.status IN ('CANCELLING','CANCELLED');
SELECT COUNT(*) FROM auth_db.user_role ur LEFT JOIN auth_db.user u ON u.id=ur.user_id LEFT JOIN auth_db.role r ON r.id=ur.role_id WHERE u.id IS NULL OR r.id IS NULL;
SELECT COUNT(*) FROM auth_db.role_permission rp LEFT JOIN auth_db.role r ON r.id=rp.role_id LEFT JOIN auth_db.permission p ON p.id=rp.permission_id WHERE r.id IS NULL OR p.id IS NULL;
SELECT COUNT(*) FROM auth_db.user u LEFT JOIN facility_db.facility f ON f.facility_code=u.facility_code WHERE f.id IS NULL;
SELECT COUNT(*) FROM facility_db.facility f LEFT JOIN facility_db.facility_type t ON t.code=f.type_code WHERE t.id IS NULL;
SELECT COUNT(*) FROM facility_db.facility f LEFT JOIN facility_db.facility p ON p.facility_code=f.parent_facility_code WHERE f.parent_facility_code IS NOT NULL AND p.id IS NULL;
SELECT COUNT(*) FROM dispatch_db.dispatch_batch_bag bb JOIN dispatch_db.dispatch_batch d ON d.batch_no=bb.batch_no WHERE bb.active_flag=1 AND d.status='CANCELLED';
SELECT COUNT(*) FROM dispatch_db.dispatch_forward_inbox f LEFT JOIN dispatch_db.dispatch_batch b ON b.manifest_no=f.manifest_no WHERE b.batch_no IS NULL OR b.source_org_code IS NULL OR b.destination_org_code IS NULL OR b.facility_route_code IS NULL;
SELECT COUNT(*) FROM sorting_db.sorting_bag_position p LEFT JOIN sorting_db.sorting_bag_handoff h ON h.manifest_no=p.outgoing_manifest_no AND h.bag_no=p.bag_no WHERE p.outgoing_manifest_no IS NOT NULL AND (h.bag_no IS NULL OR NOT ((h.status='RESERVED' AND p.container_status='SEALED') OR (h.status='MISSING' AND p.container_status='MISSING')) OR h.previous_event_no<>p.last_event_no OR h.source_org_code<>p.facility_code);
SELECT COUNT(*) FROM sorting_db.sorting_bag_handoff h LEFT JOIN sorting_db.sorting_bag_position p ON p.bag_no=h.bag_no WHERE h.status='RESERVED' AND (p.bag_no IS NULL OR NOT(p.outgoing_manifest_no <=> h.manifest_no));
SELECT COUNT(*) FROM facility_db.facility_route r LEFT JOIN facility_db.facility a ON a.facility_code=r.origin_facility_code LEFT JOIN facility_db.facility b ON b.facility_code=r.destination_facility_code WHERE a.id IS NULL OR b.id IS NULL;
SELECT COUNT(*) FROM facility_db.demo_postal_island i LEFT JOIN facility_db.demo_postal_region r ON r.region_code=i.region_code WHERE r.region_code IS NULL;
SELECT COUNT(*) FROM facility_db.demo_facility_profile p LEFT JOIN facility_db.facility f ON f.facility_code=p.facility_code LEFT JOIN facility_db.demo_postal_island i ON i.island_code=p.island_code WHERE f.id IS NULL OR i.island_code IS NULL;
SELECT COUNT(*) FROM dispatch_db.route_rule r LEFT JOIN facility_db.facility a ON a.facility_code=r.source_facility_code LEFT JOIN facility_db.facility b ON b.facility_code=r.target_facility_code WHERE a.id IS NULL OR b.id IS NULL;
SELECT COUNT(*) FROM transport_db.transport_route r LEFT JOIN facility_db.facility_route f ON f.route_code=r.facility_route_code WHERE f.id IS NULL OR f.origin_facility_code<>r.origin_facility_id OR f.destination_facility_code<>r.destination_facility_id OR f.transport_mode<>r.transport_type;
SELECT COUNT(*) FROM transport_db.transport_schedule s LEFT JOIN transport_db.transport_asset a ON a.id=s.asset_id LEFT JOIN transport_db.transport_route r ON r.id=s.route_id WHERE a.id IS NULL OR r.id IS NULL OR s.arrival_time<=s.departure_time;
SELECT COUNT(*) FROM oms_db.country_service_type c LEFT JOIN oms_db.country a ON a.code=c.country_code LEFT JOIN oms_db.service_type s ON s.code=c.service_type_code WHERE a.id IS NULL OR s.id IS NULL;
SELECT ABS(COUNT(*)-4) FROM auth_db.role WHERE code IN ('ADMIN','CLERK','MANAGER','SORTER');
SELECT ABS(COUNT(*)-4) FROM oms_db.mail_type WHERE code IN ('U','C','E','R');
SELECT ABS(COUNT(*)-1) FROM postage_db.postage_tariff_lock WHERE id=1;
SELECT ABS(COUNT(*)-1) FROM postage_db.postage_acceptance_lock WHERE id=1;
SELECT ABS(COUNT(*)-1) FROM postage_db.postage_stamp_policy WHERE id=1;
SELECT COUNT(*) FROM sorting_db.sorting_manifest_version v LEFT JOIN sorting_db.sorting_manifest m ON m.manifest_no=v.manifest_no WHERE m.manifest_no IS NULL;
SELECT COUNT(*) FROM dispatch_db.dispatch_manifest_outbox o WHERE o.version_no < 1;
SELECT COUNT(*) FROM sorting_db.sorting_manifest_seal s LEFT JOIN sorting_db.sorting_manifest_version v ON v.manifest_no=s.manifest_no AND v.version_no=s.version_no WHERE v.manifest_no IS NULL OR s.content_hash<>v.content_hash;
SELECT COUNT(*) FROM sorting_db.sorting_manifest m LEFT JOIN sorting_db.sorting_manifest_seal s ON s.manifest_no=m.manifest_no WHERE m.manifest_status='SEALED' AND (s.manifest_no IS NULL OR s.version_no<>m.version_no OR NOT (s.content_hash <=> m.content_hash));
SELECT COUNT(*) FROM dispatch_db.dispatch_manifest_outbox o WHERE o.event_type NOT IN ('PREALERT','SEAL','CANCEL') OR o.status NOT IN ('PENDING','SENDING','RETRY','SENT','CONFLICT') OR (o.event_type IN ('SEAL','CANCEL') AND o.status='SENT' AND o.receipt_json IS NULL);
SELECT COUNT(*) FROM sorting_db.sorting_manifest_cancel c LEFT JOIN sorting_db.sorting_manifest_version v ON v.manifest_no=c.manifest_no AND v.version_no=c.version_no LEFT JOIN sorting_db.sorting_manifest m ON m.manifest_no=c.manifest_no WHERE v.manifest_no IS NULL OR NOT(c.content_hash <=> v.content_hash) OR m.manifest_status<>'CANCELLED' OR m.version_no<>c.version_no;
SELECT COUNT(*) FROM sorting_db.sorting_manifest m LEFT JOIN sorting_db.sorting_manifest_cancel c ON c.manifest_no=m.manifest_no WHERE m.manifest_status='CANCELLED' AND c.manifest_no IS NULL;
SELECT COUNT(*) FROM dispatch_db.dispatch_manifest_outbox o LEFT JOIN dispatch_db.dispatch_batch b ON b.manifest_no=o.manifest_no WHERE o.event_type='CANCEL' AND (b.batch_no IS NULL OR b.status NOT IN ('CANCELLING','CANCELLED') OR (o.status='SENT' AND b.status<>'CANCELLED') OR (b.status='CANCELLED' AND o.status<>'SENT'));
SELECT COUNT(*) FROM dispatch_db.dispatch_batch b LEFT JOIN dispatch_db.dispatch_manifest_outbox o ON o.manifest_no=b.manifest_no AND o.event_type='CANCEL' WHERE b.status IN ('CANCELLING','CANCELLED') AND o.event_no IS NULL;
SELECT COUNT(*) FROM dispatch_db.handoff_record h JOIN dispatch_db.dispatch_batch b ON b.batch_no=h.batch_no WHERE b.status IN ('CANCELLING','CANCELLED');
SELECT COUNT(*) FROM sorting_db.sorting_manifest m LEFT JOIN sorting_db.sorting_manifest_version v ON v.manifest_no=m.manifest_no AND v.version_no=m.version_no WHERE m.version_no>0 AND (v.manifest_no IS NULL OR NOT (m.content_hash <=> v.content_hash) OR m.expected_package_qty<>v.expected_package_qty OR m.expected_item_qty<>v.expected_item_qty);
SELECT COUNT(*) FROM dispatch_db.dispatch_bag b LEFT JOIN dispatch_db.dispatch_bag_packing p ON p.bag_no=b.bag_no WHERE p.bag_no IS NULL;
SELECT COUNT(*) FROM dispatch_db.dispatch_bag_packing p WHERE p.packing_version<>1 OR p.sync_status NOT IN ('PENDING','SENDING','RETRY','CONFIRMED','CONFLICT') OR p.attempt_count<0 OR (p.sync_status='CONFIRMED' AND p.confirmed_at IS NULL);
SELECT COUNT(*) FROM dispatch_db.dispatch_bag b LEFT JOIN (SELECT bag_no,COUNT(*) AS item_count,CASE WHEN SUM(weight_grams IS NULL)>0 THEN NULL ELSE SUM(weight_grams) END AS item_weight FROM dispatch_db.dispatch_bag_item GROUP BY bag_no) i ON i.bag_no=b.bag_no WHERE i.bag_no IS NULL OR b.mail_count<>i.item_count OR NOT (b.total_weight_grams <=> i.item_weight);
SELECT COUNT(*) FROM dispatch_db.dispatch_bag_packing p LEFT JOIN (SELECT bag_no,COUNT(*) AS item_count,MAX(seq_no) AS max_seq,MIN(seq_no) AS min_seq FROM dispatch_db.dispatch_bag_item GROUP BY bag_no) i ON i.bag_no=p.bag_no WHERE i.bag_no IS NULL OR i.min_seq<>1 OR i.max_seq<>i.item_count OR NOT (JSON_LENGTH(p.payload_json,'$.items') <=> i.item_count);
